32: // ParseTranscript parses a conversation transcript from the given directory.
33: // It prioritizes transcript_full.jsonl, then chunks, then transcript.jsonl.
34: func ParseTranscript(baseDir string) ([]Step, error) {
35: 	var reader io.ReadCloser
36: 
37: 	fullPath := filepath.Join(baseDir, "transcript_full.jsonl")
38: 	if f, err := os.Open(fullPath); err == nil {
39: 		reader = f
40: 	} else if os.IsNotExist(err) {
41: 		// try chunks
42: 		chunksDir := filepath.Join(baseDir, "chunks", "transcript_full")
43: 		entries, err := os.ReadDir(chunksDir)
44: 		if err == nil {
45: 			var chunkFiles []string
46: 			for _, entry := range entries {
47: 				if !entry.IsDir() && filepath.Ext(entry.Name()) == ".jsonl" {
48: 					chunkFiles = append(chunkFiles, entry.Name())
49: 				}
50: 			}
51: 			if len(chunkFiles) > 0 {
52: 				sort.Strings(chunkFiles)
53: 				var readers []io.Reader
54: 				var closers []io.Closer
55: 				for _, cf := range chunkFiles {
56: 					f, err := os.Open(filepath.Join(chunksDir, cf))
57: 					if err != nil {
58: 						// cleanup
59: 						for _, c := range closers {
60: 							c.Close()
61: 						}
62: 						return nil, err
63: 					}
64: 					readers = append(readers, f)
65: 					closers = append(closers, f)
66: 				}
67: 				reader = &multiReadCloser{
68: 					Reader:  io.MultiReader(readers...),
69: 					closers: closers,
70: 				}
71: 			}
72: 		}
73: 
74: 		if reader == nil {
75: 			// fallback to compact
76: 			compactPath := filepath.Join(baseDir, "transcript.jsonl")
77: 			if f, err := os.Open(compactPath); err == nil {
78: 				reader = f
79: 			} else {
80: 				return nil, fmt.Errorf("no transcript source found in %s", baseDir)
81: 			}
82: 		}
83: 	} else {
84: 		return nil, err
85: 	}
86: 
87: 	defer reader.Close()
88: 
89: 	var steps []Step
90: 	scanner := bufio.NewScanner(reader)
91: 	// Some jsonl lines could be very long
92: 	buf := make([]byte, 1024*1024)
93: 	scanner.Buffer(buf, 1024*1024*50) // up to 50MB per line
94: 
95: 	expectedIndex := 0
96: 	for scanner.Scan() {
97: 		line := scanner.Text()
98: 		if line == "CHECKPOINT" {
99: 			steps = append(steps, Step{IsCheckpoint: true})
100: 			continue
101: 		}
102: 
103: 		var step Step
104: 		if err := json.Unmarshal([]byte(line), &step); err != nil {
105: 			return nil, fmt.Errorf("failed to parse JSON: %w", err)
106: 		}
107: 
108: 		if step.StepIndex > expectedIndex {
109: 			steps = append(steps, Step{
110: 				IsGap:   true,
111: 				GapSize: step.StepIndex - expectedIndex,
112: 			})
113: 		}
114: 
115: 		expectedIndex = step.StepIndex + 1
116: 		steps = append(steps, step)
117: 	}
118: 
119: 	if err := scanner.Err(); err != nil {
120: 		return nil, fmt.Errorf("scanner error: %w", err)
121: 	}
122: 
123: 	return steps, nil
124: }
