// Package spool manages the event-path spool directory, durable spool entries,
// and incremental transcript copying into the queue.
package spool

package spool

import (
	"encoding/json"
	"time"
)

// EntryKind specifies the category of work requested via the spool.
type EntryKind string

const (
	// KindCapture indicates a finished agent turn / session requiring transcript capture.
	KindCapture EntryKind = "capture"
	// KindBrief indicates a request for task brief generation.
	KindBrief EntryKind = "brief"
	// KindDejavu indicates a tier-2 semantic déjà-vu check request.
	KindDejavu EntryKind = "dejavu"
	// KindRecheck indicates a re-check requested following dependency or git changes.
	KindRecheck EntryKind = "recheck"
)

// Entry represents a durable unit of work spooled by hooks for ingestion by the tick.
type Entry struct {
	ID             string         `json:"id,omitempty"`
	Kind           EntryKind      `json:"kind,omitempty"`
	Timestamp      time.Time      `json:"timestamp,omitempty"`
	Harness        string         `json:"harness,omitempty"`
	ConversationID string         `json:"conversation_id,omitempty"`
	SessionID      string         `json:"session_id,omitempty"`
	TranscriptPath string         `json:"transcript_path,omitempty"`
	RepoRoot       string         `json:"repo_root,omitempty"`
	Branch         string         `json:"branch,omitempty"`
	Head           string         `json:"head,omitempty"`
	StepIndex      int            `json:"step_index,omitempty"`
	EntityID       string         `json:"entity_id,omitempty"`
	Reasoning      string         `json:"reasoning,omitempty"`
	Command        string         `json:"command,omitempty"`
	Details        map[string]any `json:"details,omitempty"`
}

// UnmarshalJSON unmarshals JSON and normalizes defaults (such as defaulting Kind to KindCapture).
func (e *Entry) UnmarshalJSON(data []byte) error {
	type Alias Entry
	aux := &struct {
		*Alias
	}{
		Alias: (*Alias)(e),
	}
	if err := json.Unmarshal(data, aux); err != nil {
		return err
	}
	if e.Kind == "" {
		if e.TranscriptPath != "" || e.ConversationID != "" {
			e.Kind = KindCapture
		}
	}
	return nil
}

// NewCaptureEntry creates a spool entry for a finished agent session turn.
func NewCaptureEntry(harness, conversationID, transcriptPath, repoRoot, branch, head string) Entry {
	return Entry{
		Kind:           KindCapture,
		Timestamp:      time.Now().UTC(),
		Harness:        harness,
		ConversationID: conversationID,
		TranscriptPath: transcriptPath,
		RepoRoot:       repoRoot,
		Branch:         branch,
		Head:           head,
	}
}

// NewBriefEntry creates a spool entry requesting task brief generation.
func NewBriefEntry(harness, conversationID, repoRoot string, stepIndex int, reasoning string) Entry {
	return Entry{
		Kind:           KindBrief,
		Timestamp:      time.Now().UTC(),
		Harness:        harness,
		ConversationID: conversationID,
		RepoRoot:       repoRoot,
		StepIndex:      stepIndex,
		Reasoning:      reasoning,
	}
}

// NewDejavuEntry creates a spool entry requesting a tier-2 semantic déjà-vu check.
func NewDejavuEntry(harness, conversationID, entityID, reasoning string, stepIndex int) Entry {
	return Entry{
		Kind:           KindDejavu,
		Timestamp:      time.Now().UTC(),
		Harness:        harness,
		ConversationID: conversationID,
		EntityID:       entityID,
		Reasoning:      reasoning,
		StepIndex:      stepIndex,
	}
}

// NewRecheckEntry creates a spool entry requesting a re-verification after a git operation or dependency update.
func NewRecheckEntry(harness, conversationID, repoRoot, branch, head, command string, stepIndex int) Entry {
	return Entry{
		Kind:           KindRecheck,
		Timestamp:      time.Now().UTC(),
		Harness:        harness,
		ConversationID: conversationID,
		RepoRoot:       repoRoot,
		Branch:         branch,
		Head:           head,
		Command:        command,
		StepIndex:      stepIndex,
	}
}

package spool

import (
	"encoding/json"
	"testing"
	"time"
)

func TestEntry_JSONSerialization(t *testing.T) {
	entry := NewCaptureEntry("antigravity", "conv-123", "/path/to/transcript.jsonl", "/repo", "main", "abc1234")
	entry.ID = "test-id-1"

	data, err := json.Marshal(entry)
	if err != nil {
		t.Fatalf("failed to marshal entry: %v", err)
	}

	var parsed Entry
	if err := json.Unmarshal(data, &parsed); err != nil {
		t.Fatalf("failed to unmarshal entry: %v", err)
	}

	if parsed.ID != "test-id-1" {
		t.Errorf("expected ID 'test-id-1', got %s", parsed.ID)
	}
	if parsed.Kind != KindCapture {
		t.Errorf("expected kind %s, got %s", KindCapture, parsed.Kind)
	}
	if parsed.ConversationID != "conv-123" {
		t.Errorf("expected conv-123, got %s", parsed.ConversationID)
	}
	if parsed.TranscriptPath != "/path/to/transcript.jsonl" {
		t.Errorf("expected /path/to/transcript.jsonl, got %s", parsed.TranscriptPath)
	}
	if parsed.RepoRoot != "/repo" {
		t.Errorf("expected /repo, got %s", parsed.RepoRoot)
	}
	if parsed.Branch != "main" {
		t.Errorf("expected main, got %s", parsed.Branch)
	}
	if parsed.Head != "abc1234" {
		t.Errorf("expected abc1234, got %s", parsed.Head)
	}
}

func TestEntry_DefaultKind(t *testing.T) {
	// Raw JSON without explicit kind field
	raw := `{"conversation_id":"c1","transcript_path":"/t.jsonl"}`
	var parsed Entry
	if err := json.Unmarshal([]byte(raw), &parsed); err != nil {
		t.Fatalf("failed to unmarshal: %v", err)
	}
	if parsed.Kind != KindCapture {
		t.Errorf("expected default kind %s, got %s", KindCapture, parsed.Kind)
	}
}

func TestConstructors(t *testing.T) {
	b := NewBriefEntry("antigravity", "c2", "/repo", 4, "planning refactor")
	if b.Kind != KindBrief || b.StepIndex != 4 || b.Reasoning != "planning refactor" {
		t.Errorf("unexpected brief entry: %+v", b)
	}
	if b.Timestamp.IsZero() {
		t.Error("expected non-zero timestamp")
	}

	d := NewDejavuEntry("antigravity", "c3", "ent-456", "re-trying ruled-out approach", 10)
	if d.Kind != KindDejavu || d.EntityID != "ent-456" || d.StepIndex != 10 {
		t.Errorf("unexpected dejavu entry: %+v", d)
	}

	r := NewRecheckEntry("antigravity", "c4", "/repo", "feat", "def5678", "git pull", 2)
	if r.Kind != KindRecheck || r.Command != "git pull" || r.Branch != "feat" {
		t.Errorf("unexpected recheck entry: %+v", r)
	}
}

package spool

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// Writer writes durable spool entries into the spool directory.
type Writer struct {
	spoolDir string
}

// NewWriter returns a new Writer targeting the given spool directory.
func NewWriter(spoolDir string) *Writer {
	return &Writer{spoolDir: spoolDir}
}

// SpoolDir returns the configured spool directory path.
func (w *Writer) SpoolDir() string {
	return w.spoolDir
}

// Write writes the given spool entry to a unique temporary file in the spool directory,
// flushes and closes it, and then atomically renames it to its final destination name.
// Respects Windows file-locking semantics by closing all handles prior to rename.
func (w *Writer) Write(entry Entry) (string, error) {
	if w.spoolDir == "" {
		return "", fmt.Errorf("spool directory cannot be empty")
	}

	if err := os.MkdirAll(w.spoolDir, 0755); err != nil {
		return "", fmt.Errorf("creating spool directory: %w", err)
	}

	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now().UTC()
	} else {
		entry.Timestamp = entry.Timestamp.UTC()
	}

	if entry.Kind == "" {
		entry.Kind = KindCapture
	}

	if entry.ID == "" {
		suffix, err := randomHex(6)
		if err != nil {
			suffix = fmt.Sprintf("%06x", time.Now().UnixNano()%0xffffff)
		}
		entry.ID = fmt.Sprintf("spool-%d-%s", entry.Timestamp.UnixNano(), suffix)
	}

	data, err := json.MarshalIndent(entry, "", "  ")
	if err != nil {
		return "", fmt.Errorf("marshaling spool entry: %w", err)
	}

	// 1. Create temporary file directly in spoolDir (same filesystem for atomic rename).
	// The leading dot ensures readers filter it out while in-progress.
	tmpFile, err := os.CreateTemp(w.spoolDir, ".spool_tmp_*")
	if err != nil {
		return "", fmt.Errorf("creating temp spool file: %w", err)
	}
	tmpPath := tmpFile.Name()

	// 2. Write data and flush to disk.
	if _, err := tmpFile.Write(data); err != nil {
		tmpFile.Close()
		os.Remove(tmpPath)
		return "", fmt.Errorf("writing spool entry: %w", err)
	}
	if err := tmpFile.Sync(); err != nil {
		tmpFile.Close()
		os.Remove(tmpPath)
		return "", fmt.Errorf("syncing spool entry: %w", err)
	}

	// 3. Close the file handle BEFORE renaming.
	// On Windows, attempting to rename an open file fails with ERROR_ACCESS_DENIED.
	if err := tmpFile.Close(); err != nil {
		os.Remove(tmpPath)
		return "", fmt.Errorf("closing temp spool file: %w", err)
	}

	// 4. Construct final destination filename.
	// Lexicographically sortable timestamp without colons (safe for Windows filenames).
	tsFormatted := entry.Timestamp.Format("20060102T150405.000000000Z")
	finalFilename := fmt.Sprintf("%s_%s_%s.json", tsFormatted, entry.Kind, entry.ID)
	destPath := filepath.Join(w.spoolDir, finalFilename)

	// 5. Atomically rename with retry loop for Windows file-system edge cases.
	if err := atomicRename(tmpPath, destPath); err != nil {
		os.Remove(tmpPath)
		return "", fmt.Errorf("renaming temp spool file: %w", err)
	}

	return destPath, nil
}

// Write writes an entry using a new Writer for the given spool directory.
func Write(spoolDir string, entry Entry) (string, error) {
	return NewWriter(spoolDir).Write(entry)
}

func randomHex(bytes int) (string, error) {
	b := make([]byte, bytes)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// atomicRename renames src to dst, retrying briefly on Windows if a transient sharing lock occurs.
func atomicRename(src, dst string) error {
	var lastErr error
	for i := 0; i < 5; i++ {
		err := os.Rename(src, dst)
		if err == nil {
			return nil
		}
		lastErr = err
		time.Sleep(time.Duration(5*(i+1)) * time.Millisecond)
	}
	return lastErr
}

